<?php

declare(strict_types=1);

namespace App\Entity;

use App\Enum\FilingPartRole;
use App\Enum\SignatureStatus;
use App\Repository\FilingPackagePartRepository;
use Doctrine\DBAL\Types\Types;
use Doctrine\ORM\Mapping as ORM;

/**
 * One physical file of a filing package. The unsigned file is generated by the
 * platform; the signed one is the lawyer's and is never rewritten or compressed.
 */
#[ORM\Entity(repositoryClass: FilingPackagePartRepository::class)]
class FilingPackagePart
{
    #[ORM\Id]
    #[ORM\GeneratedValue]
    #[ORM\Column]
    private ?int $id = null;

    #[ORM\ManyToOne(targetEntity: FilingPackage::class, inversedBy: 'parts')]
    #[ORM\JoinColumn(nullable: false, onDelete: 'CASCADE')]
    private FilingPackage $package;

    #[ORM\Column(length: 30, enumType: FilingPartRole::class)]
    private FilingPartRole $role;

    #[ORM\Column]
    private int $position;

    #[ORM\Column(nullable: true)]
    private ?int $volume = null;

    #[ORM\Column(nullable: true)]
    private ?int $volumeCount = null;

    #[ORM\Column(length: 255)]
    private string $title;

    #[ORM\Column]
    private int $pageCount;

    /** First page of this file in the continuous annex numbering; null outside the annexes. */
    #[ORM\Column(nullable: true)]
    private ?int $annexPageFrom = null;

    #[ORM\Column(nullable: true)]
    private ?int $annexPageTo = null;

    /** @var list<int> */
    #[ORM\Column(type: Types::JSON)]
    private array $sourceDocumentIds = [];

    /** Written into the unsigned PDF's Info dictionary, so a signed upload can be traced back. */
    #[ORM\Column(length: 32, unique: true, options: ['fixed' => true])]
    private string $partToken;

    #[ORM\Column(length: 255)]
    private string $unsignedPath;

    #[ORM\Column(length: 64, options: ['fixed' => true])]
    private string $unsignedSha256;

    #[ORM\Column]
    private int $unsignedBytes;

    #[ORM\Column]
    private bool $compressionApplied = false;

    #[ORM\Column(length: 255, nullable: true)]
    private ?string $signedPath = null;

    #[ORM\Column(length: 64, nullable: true, options: ['fixed' => true])]
    private ?string $signedSha256 = null;

    #[ORM\Column(nullable: true)]
    private ?int $signedBytes = null;

    #[ORM\Column(nullable: true)]
    private ?\DateTimeImmutable $signedUploadedAt = null;

    #[ORM\ManyToOne(targetEntity: User::class)]
    #[ORM\JoinColumn(onDelete: 'SET NULL')]
    private ?User $signedUploadedBy = null;

    #[ORM\Column(length: 30, enumType: SignatureStatus::class)]
    private SignatureStatus $signatureStatus = SignatureStatus::MISSING;

    #[ORM\ManyToOne(targetEntity: User::class)]
    #[ORM\JoinColumn(onDelete: 'SET NULL')]
    private ?User $probableMatchConfirmedBy = null;

    #[ORM\Column(nullable: true)]
    private ?\DateTimeImmutable $probableMatchConfirmedAt = null;

    /** @var array<string, mixed>|null */
    #[ORM\Column(type: Types::JSON, nullable: true)]
    private ?array $signatureReport = null;

    /**
     * @param list<int> $sourceDocumentIds
     */
    public function __construct(
        FilingPartRole $role,
        int $position,
        string $title,
        int $pageCount,
        string $unsignedPath,
        string $unsignedSha256,
        int $unsignedBytes,
        string $partToken,
        array $sourceDocumentIds = [],
    ) {
        $this->role = $role;
        $this->position = $position;
        $this->title = $title;
        $this->pageCount = $pageCount;
        $this->unsignedPath = $unsignedPath;
        $this->unsignedSha256 = $unsignedSha256;
        $this->unsignedBytes = $unsignedBytes;
        $this->partToken = $partToken;
        $this->sourceDocumentIds = $sourceDocumentIds;
    }

    /**
     * Same file, same signature state, attached to another package version.
     * The token is new because it identifies the part row, not the bytes.
     */
    public function copyForPackage(string $partToken, int $position): self
    {
        $copy = clone $this;
        $copy->id = null;
        $copy->partToken = $partToken;
        $copy->position = $position;

        return $copy;
    }

    public function getId(): ?int
    {
        return $this->id;
    }

    public function getPackage(): FilingPackage
    {
        return $this->package;
    }

    public function setPackage(FilingPackage $package): static
    {
        $this->package = $package;

        return $this;
    }

    public function getRole(): FilingPartRole
    {
        return $this->role;
    }

    public function getPosition(): int
    {
        return $this->position;
    }

    public function getVolume(): ?int
    {
        return $this->volume;
    }

    public function getVolumeCount(): ?int
    {
        return $this->volumeCount;
    }

    public function setVolume(?int $volume, ?int $volumeCount): static
    {
        $this->volume = $volume;
        $this->volumeCount = $volumeCount;

        return $this;
    }

    public function getTitle(): string
    {
        return $this->title;
    }

    public function getPageCount(): int
    {
        return $this->pageCount;
    }

    public function getAnnexPageFrom(): ?int
    {
        return $this->annexPageFrom;
    }

    public function getAnnexPageTo(): ?int
    {
        return $this->annexPageTo;
    }

    public function setAnnexPageRange(?int $from, ?int $to): static
    {
        $this->annexPageFrom = $from;
        $this->annexPageTo = $to;

        return $this;
    }

    /** @return list<int> */
    public function getSourceDocumentIds(): array
    {
        return $this->sourceDocumentIds;
    }

    public function getPartToken(): string
    {
        return $this->partToken;
    }

    public function getUnsignedPath(): string
    {
        return $this->unsignedPath;
    }

    public function getUnsignedSha256(): string
    {
        return $this->unsignedSha256;
    }

    public function getUnsignedBytes(): int
    {
        return $this->unsignedBytes;
    }

    public function isCompressionApplied(): bool
    {
        return $this->compressionApplied;
    }

    public function setCompressionApplied(bool $compressionApplied): static
    {
        $this->compressionApplied = $compressionApplied;

        return $this;
    }

    public function getSignedPath(): ?string
    {
        return $this->signedPath;
    }

    public function getSignedSha256(): ?string
    {
        return $this->signedSha256;
    }

    public function getSignedBytes(): ?int
    {
        return $this->signedBytes;
    }

    public function getSignedUploadedAt(): ?\DateTimeImmutable
    {
        return $this->signedUploadedAt;
    }

    public function getSignedUploadedBy(): ?User
    {
        return $this->signedUploadedBy;
    }

    public function getSignatureStatus(): SignatureStatus
    {
        return $this->signatureStatus;
    }

    public function getProbableMatchConfirmedBy(): ?User
    {
        return $this->probableMatchConfirmedBy;
    }

    public function getProbableMatchConfirmedAt(): ?\DateTimeImmutable
    {
        return $this->probableMatchConfirmedAt;
    }

    /** @return array<string, mixed>|null */
    public function getSignatureReport(): ?array
    {
        return $this->signatureReport;
    }

    /** @return list<string> */
    public function getSignatureWarnings(): array
    {
        return array_values($this->signatureReport['warnings'] ?? []);
    }

    /**
     * What a probable match tolerated, as translation keys with their parameters.
     * Reports stored before these notes existed have none.
     *
     * @return list<array{key: string, params: array<string, string|int>}>
     */
    public function getSignatureMatchNotes(): array
    {
        return array_values($this->signatureReport['matchNotes'] ?? []);
    }

    /**
     * Records an accepted signed file. Refused outcomes never reach the part, so
     * the previous accepted file stays in place. A text-only match carries the
     * lawyer's confirmation only when given for this very file.
     *
     * @param array<string, mixed> $report
     */
    public function recordSignedUpload(
        string $path,
        string $sha256,
        int $bytes,
        User $uploadedBy,
        SignatureStatus $status,
        array $report,
    ): static {
        if (!in_array($status, [SignatureStatus::PRESENT_MATCHED, SignatureStatus::PRESENT_PROBABLE], true)) {
            throw new \LogicException('Only a detected and matched signature is recorded on a part.');
        }

        $this->signedPath = $path;
        $this->signedSha256 = $sha256;
        $this->signedBytes = $bytes;
        $this->signedUploadedAt = new \DateTimeImmutable();
        $this->signedUploadedBy = $uploadedBy;
        $this->signatureStatus = $status;
        $this->signatureReport = $report;

        // A text-only match is confirmed afterwards, once the lawyer has seen its warnings.
        $this->probableMatchConfirmedBy = null;
        $this->probableMatchConfirmedAt = null;

        return $this;
    }

    public function confirmProbableMatch(User $user): static
    {
        if (!$this->isAwaitingProbableConfirmation()) {
            throw new \LogicException('Only an unconfirmed text-only match can be confirmed.');
        }

        $this->probableMatchConfirmedBy = $user;
        $this->probableMatchConfirmedAt = new \DateTimeImmutable();

        return $this;
    }

    public function isAwaitingProbableConfirmation(): bool
    {
        return $this->signatureStatus === SignatureStatus::PRESENT_PROBABLE && $this->probableMatchConfirmedAt === null;
    }

    public function isSignatureAccepted(): bool
    {
        return $this->signatureStatus === SignatureStatus::PRESENT_MATCHED
            || ($this->signatureStatus === SignatureStatus::PRESENT_PROBABLE && $this->probableMatchConfirmedAt !== null);
    }

    public function hasSignedFile(): bool
    {
        return $this->signedPath !== null;
    }
}
